const response = $input.first().json;
const eventUrl = $('HTML to Markdown').first().json.eventUrl;

let extracted;
try {
  const content = response.choices[0].message.content;
  extracted = JSON.parse(content);
} catch (e) {
  return [{ json: { error: 'Failed to parse OpenAI response', eventUrl } }];
}

return [{
  json: {
    url: eventUrl,
    title: extracted.title || 'Unknown Event',
    start_date: extracted.start_date || null,
    end_date: extracted.end_date || null,
    location: extracted.location || null,
    venue: extracted.venue || null,
    speakers: JSON.stringify(extracted.speakers || []),
    summary: extracted.summary || '',
    created_at: new Date().toISOString()
  }
}];

const event = $('Parse OpenAI Response').first().json;
const subscribers = $input.all().map(item => item.json);

// Parse speakers back to array for display
let speakers = [];
try {
  speakers = JSON.parse(event.speakers || '[]');
} catch(e) {}

const speakersText = speakers.length > 0 ? speakers.join(', ') : 'TBA';

const emailHtml = `
<h2>${event.title}</h2>
<p><strong>Date:</strong> ${event.start_date}${event.end_date !== event.start_date ? ' - ' + event.end_date : ''}</p>
<p><strong>Location:</strong> ${event.location || 'TBA'}${event.venue ? ' (' + event.venue + ')' : ''}</p>
<p><strong>Speakers:</strong> ${speakersText}</p>
<p>${event.summary}</p>
<p><a href="${event.url}">More details →</a></p>
`;

const telegramText = `🎤 *${event.title}*\n\n📅 ${event.start_date}${event.end_date !== event.start_date ? ' - ' + event.end_date : ''}\n📍 ${event.location || 'TBA'}${event.venue ? ' (' + event.venue + ')' : ''}\n👤 ${speakersText}\n\n${event.summary}\n\n🔗 ${event.url}`;

return subscribers.map(sub => ({
  json: {
    ...sub,
    event,
    emailHtml,
    telegramText
  }
}));
